mapper.select:
select * from psy_scale


        and scale_name like concat('%', #{scaleName}, '%')


        and status = #{status}


        and scale_type = #{scaleType}


order by scale_id desc

mapper.update:
update psy_appointment
set evaluation_content = #{evaluationContent},
    evaluation_score = #{evaluationScore},
    update_time = sysdate()
where appointment_id = #{appointmentId}
  and student_user_id = #{studentUserId}

mapper.select:
select * from psy_message
where receiver_user_id = #{userId}
order by create_time desc

    limit #{limit}

select w.*,
       sp.real_name as student_name,
       cp.real_name as counselor_name
from psy_warning w
left join psy_student_profile sp on w.student_user_id = sp.user_id
left join psy_counselor_profile cp on w.counselor_user_id = cp.user_id


        and w.warning_id = #{warningId}


        and w.student_user_id = #{studentUserId}


        and w.counselor_user_id = #{counselorUserId}


        and w.risk_level = #{riskLevel}


        and w.status = #{status}


        and w.warning_source = #{warningSource}


        and sp.real_name like concat('%', #{studentName}, '%')


order by field(w.status, '待处理', '处理中', '已处理'), field(w.risk_level, '高风险', '中风险', '关注', '正常'), w.create_time desc

mapper.update:
update psy_warning
risk_level = #{riskLevel}, status = #{status}, counselor_user_id = #{counselorUserId}, process_note = #{processNote}, follow_plan = #{followPlan}, handled_time = #{handledTime}, update_by = #{updateBy}, update_time = sysdate()
where warning_id = #{warningId}

update psy_scale
scale_code = #{scaleCode}, scale_name = #{scaleName}, scale_type = #{scaleType}, description = #{description}, question_count = #{questionCount}, max_score = #{maxScore}, warning_threshold = #{warningThreshold}, status = #{status}, result_template = #{resultTemplate}, update_by = #{updateBy}, update_time = sysdate()
where scale_id = #{scaleId}
